1	/**
2	 * Phase 4 E2E Validation Tests
3	 *
4	 * Validates Phase 4 acceptance criteria:
5	 * 1. Users API: list, register, revoke, regenerate token
6	 * 2. Users Page UI: navigation, register dialog, token display, revoke, regenerate
7	 * 3. Sync API: push and pull endpoints
8	 * 4. Sync UI: Push/Pull buttons in header with status indicators
9	 *
10	 * Known bugs (documented):
11	 * - BUG-1: POST /api/users/:name/regenerate fails in open mode because
12	 *   usersRegenerate requires self-service auth (resolved author must match
13	 *   target user name). Server doesn't forward user token. The Tracker's
14	 *   resolveAuthor returns "anonymous" in open mode which doesn't match the
15	 *   target user name.
16	 * - BUG-2: POST /api/sync/push and /api/sync/pull fail with NOT_INITIALIZED
17	 *   because the sync route passes AGENTRACK_CWD (the worktree directory)
18	 *   directly to pushWorktree/pullWorktree instead of resolving the project
19	 *   root via resolveTrackerDir. The worktree functions expect the project
20	 *   root where .agentrack.json lives, not the worktree directory itself.
21	 *
22	 * Also validates:
23	 * - Backend validation and error handling
24	 * - Frontend data display and interactions
25	 * - Navigation between Users page and Issues page
26	 */
27	import { test, expect } from "@playwright/test";
28	
29	const BASE = "http://localhost:3000";
30	
31	/**
32	 * Helper: generate a unique ID for test isolation.
33	 */
34	function uniqueId() {
35	  return `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
36	}
37	
38	/**
39	 * Helper: navigate to page and wait for the issues API to respond.
40	 */
41	async function gotoAndWaitForIssues(
42	  page: import("@playwright/test").Page,
43	  url: string = "/"
44	) {
45	  const responsePromise = page.waitForResponse(
46	    (resp) => resp.url().includes("/api/issues") && resp.status() === 200,
47	    { timeout: 15000 }
48	  );
49	  await page.goto(url);
50	  await responsePromise;
51	}
52	
53	/**
54	 * Helper: navigate to users page and wait for the users API to respond.
55	 */
56	async function gotoUsersPage(page: import("@playwright/test").Page) {
57	  const responsePromise = page.waitForResponse(
58	    (resp) => resp.url().includes("/api/users") && resp.status() === 200,
59	    { timeout: 10000 }
60	  );
61	  await page.goto("/users");
62	  await responsePromise;
63	}
64	
65	// ═══════════════════════════════════════════════════════════════════════
66	// Backend: Users API
67	// ═══════════════════════════════════════════════════════════════════════
68	
69	test.describe("Backend: GET /api/users", () => {
70	  test("returns 200 with array", async ({ request }) => {
71	    const response = await request.get(`${BASE}/api/users`);
72	    expect(response.status()).toBe(200);
73	    const body = await response.json();
74	    expect(Array.isArray(body)).toBe(true);
75	  });
76	
77	  test("returns users without tokens", async ({ request }) => {
78	    const name = `apitest-list-${uniqueId()}`;
79	    await request.post(`${BASE}/api/users`, {
80	      data: { name },
81	    });
82	
83	    const response = await request.get(`${BASE}/api/users`);
84	    const users = await response.json();
85	    const user = users.find((u: any) => u.name === name);
86	    expect(user).toBeDefined();
87	    expect(user).toHaveProperty("name");
88	    expect(user).toHaveProperty("registeredAt");
89	    expect(user).not.toHaveProperty("token");
90	  });
91	
92	  test("returns users with correct shape", async ({ request }) => {
93	    const response = await request.get(`${BASE}/api/users`);
94	    const users = await response.json();
95	    for (const user of users) {
96	      expect(user).toHaveProperty("name");
97	      expect(user).toHaveProperty("registeredAt");
98	      expect(typeof user.name).toBe("string");
99	      expect(typeof user.registeredAt).toBe("string");
100	    }
101	  });
102	});
103	
104	test.describe("Backend: POST /api/users", () => {
105	  test("registers a new user and returns 201 with token", async ({
106	    request,
107	  }) => {
108	    const name = `apitest-reg-${uniqueId()}`;
109	    const response = await request.post(`${BASE}/api/users`, {
110	      data: { name },
111	    });
112	    expect(response.status()).toBe(201);
113	    const body = await response.json();
114	    expect(body).toHaveProperty("result", "OK");
115	    expect(body).toHaveProperty("name", name);
116	    expect(body).toHaveProperty("token");
117	    expect(typeof body.token).toBe("string");
118	    expect(body.token.length).toBeGreaterThan(0);
119	  });
120	
121	  test("lowercases user name on registration", async ({ request }) => {
122	    const name = `Upper${uniqueId()}`;
123	    const response = await request.post(`${BASE}/api/users`, {
124	      data: { name },
125	    });
126	    expect(response.status()).toBe(201);
127	    const body = await response.json();
128	    expect(body.name).toBe(name.toLowerCase());
129	  });
130	
131	  test("returns 400 when name is missing", async ({ request }) => {
132	    const response = await request.post(`${BASE}/api/users`, {
133	      data: {},
134	    });
135	    expect(response.status()).toBe(400);
136	    const body = await response.json();
137	    expect(body.error).toBe(true);
138	    expect(body.code).toBe("VALIDATION_ERROR");
139	  });
140	
141	  test("returns 400 when name is empty string", async ({ request }) => {
142	    const response = await request.post(`${BASE}/api/users`, {
143	      data: { name: "   " },
144	    });
145	    expect(response.status()).toBe(400);
146	  });
147	
148	  test("returns error for duplicate name", async ({ request }) => {
149	    const name = `dup-${uniqueId()}`;
150	    await request.post(`${BASE}/api/users`, {
151	      data: { name },
152	    });
153	
154	    const response = await request.post(`${BASE}/api/users`, {
155	      data: { name },
156	    });
157	    // Should fail — duplicate name
158	    expect(response.status()).toBeGreaterThanOrEqual(400);
159	  });
160	
161	  test("rejects 'anonymous' as reserved name", async ({ request }) => {
162	    const response = await request.post(`${BASE}/api/users`, {
163	      data: { name: "anonymous" },
164	    });
165	    expect(response.status()).toBeGreaterThanOrEqual(400);
166	  });
167	});
168	
169	test.describe("Backend: DELETE /api/users/:name", () => {
170	  test("revokes a user and returns 200", async ({ request }) => {
171	    const name = `revoke-${uniqueId()}`;
172	    await request.post(`${BASE}/api/users`, {
173	      data: { name },
174	    });
175	
176	    const response = await request.delete(`${BASE}/api/users/${name}`);
177	    expect(response.status()).toBe(200);
178	    const body = await response.json();
179	    expect(body.result).toBe("OK");
180	  });
181	
182	  test("removes user from user list after revoke", async ({ request }) => {
183	    const name = `revoke-list-${uniqueId()}`;
184	    await request.post(`${BASE}/api/users`, {
185	      data: { name },
186	    });
187	
188	    await request.delete(`${BASE}/api/users/${name}`);
189	
190	    const listRes = await request.get(`${BASE}/api/users`);
191	    const users = await listRes.json();
192	    const found = users.find((u: any) => u.name === name);
193	    expect(found).toBeUndefined();
194	  });
195	});
196	
197	test.describe("Backend: POST /api/users/:name/regenerate", () => {
198	  test("returns 401 in open mode without token — BUG-1", async ({
199	    request,
200	  }) => {
201	    const name = `regen-${uniqueId()}`;
202	    await request.post(`${BASE}/api/users`, {
203	      data: { name },
204	    });
205	
206	    const response = await request.post(
207	      `${BASE}/api/users/${name}/regenerate`
208	    );
209	    // BUG-1: usersRegenerate requires self-service auth but server
210	    // doesn't forward user token. resolveAuthor returns "anonymous"
211	    // in open mode, which fails the self-service check.
212	    expect(response.status()).toBe(401);
213	    const body = await response.json();
214	    expect(body.code).toBe("INVALID_TOKEN");
215	  });
216	});
217	
218	// ═══════════════════════════════════════════════════════════════════════
219	// Backend: Sync API
220	// ═══════════════════════════════════════════════════════════════════════
221	
222	test.describe("Backend: POST /api/sync/push", () => {
223	  test("returns 500 with NOT_INITIALIZED — BUG-2", async ({ request }) => {
224	    const response = await request.post(`${BASE}/api/sync/push`);
225	    // BUG-2: sync route passes AGENTRACK_CWD (worktree dir) to pushWorktree
226	    // which expects the project root. This causes NOT_INITIALIZED.
227	    expect(response.status()).toBe(500);
228	    const body = await response.json();
229	    expect(body.code).toBe("NOT_INITIALIZED");
230	  });
231	});
232	
233	test.describe("Backend: POST /api/sync/pull", () => {
234	  test("returns 500 with NOT_INITIALIZED — BUG-2", async ({ request }) => {
235	    const response = await request.post(`${BASE}/api/sync/pull`);
236	    // BUG-2: Same root cause — AGENTRACK_CWD is the worktree dir
237	    // but pullWorktree expects the project root.
238	    expect(response.status()).toBe(500);
239	    const body = await response.json();
240	    expect(body.code).toBe("NOT_INITIALIZED");
241	  });
242	});
243	
244	// ═══════════════════════════════════════════════════════════════════════
245	// Frontend: Users Page Navigation
246	// ═══════════════════════════════════════════════════════════════════════
247	
248	test.describe("Frontend: Users Page Navigation", () => {
249	  test("navigates to Users page via header link", async ({ page }) => {
250	    await gotoAndWaitForIssues(page);
251	
252	    // Click the Users button in the header — use exact match to avoid
253	    // strict mode violations from issue titles containing "Users"
254	    const usersPromise = page.waitForResponse(
255	      (resp) => resp.url().includes("/api/users") && resp.status() === 200,
256	      { timeout: 10000 }
257	    );
258	    await page.getByRole("link", { name: "Users", exact: true }).click();
259	    await usersPromise;
260	
261	    await expect(page).toHaveURL("/users", { timeout: 10000 });
262	    await expect(
263	      page.getByRole("heading", { name: "Users" })
264	    ).toBeVisible({ timeout: 10000 });
265	  });
266	
267	  test("navigates back to issues from Users page", async ({ page }) => {
268	    await gotoUsersPage(page);
269	
270	    // Click "Back to issues" link
271	    const issuesPromise = page.waitForResponse(
272	      (resp) => resp.url().includes("/api/issues") && resp.status() === 200,
273	      { timeout: 10000 }
274	    );
275	    await page.getByRole("link", { name: /Back to issues/ }).click();
276	    await issuesPromise;
277	
278	    await expect(page).toHaveURL("/", { timeout: 10000 });
279	  });
280	});
281	
282	// ═══════════════════════════════════════════════════════════════════════
283	// Frontend: Users Page Display
284	// ═══════════════════════════════════════════════════════════════════════
285	
286	test.describe("Frontend: Users Page Display", () => {
287	  test("shows empty state when no users registered", async ({
288	    page,
289	    request,
290	  }) => {
291	    // Ensure clean state — revoke any users (they might exist from prior tests in same run)
292	    const listRes = await request.get(`${BASE}/api/users`);
293	    const existingUsers = await listRes.json();
294	    for (const u of existingUsers) {
295	      await request.delete(`${BASE}/api/users/${u.name}`);
