304	
305	  test("displays registered users with names and dates", async ({
306	    page,
307	    request,
308	  }) => {
309	    const name = `display-${uniqueId()}`;
310	    await request.post(`${BASE}/api/users`, {
311	      data: { name },
312	    });
313	
314	    await gotoUsersPage(page);
315	
316	    // Should show the user name
317	    await expect(page.getByText(name)).toBeVisible({ timeout: 10000 });
318	
