329	  });
330	
331	  test("shows user avatar with first letter", async ({ page, request }) => {
332	    const name = `avatar-${uniqueId()}`;
333	    await request.post(`${BASE}/api/users`, {
334	      data: { name },
335	    });
336	
337	    await gotoUsersPage(page);
338	
339	    // Avatar should show first letter capitalized
340	    await expect(
341	      page.locator(".rounded-full").filter({ hasText: "A" })
342	    ).toBeVisible({ timeout: 10000 });
343	  });
344	});
345	
346	// ═══════════════════════════════════════════════════════════════════════
347	// Frontend: Register User Dialog
348	// ═══════════════════════════════════════════════════════════════════════
349	
350	test.describe("Frontend: Register User Dialog", () => {
351	  test("opens register dialog on button click", async ({ page }) => {
352	    await gotoUsersPage(page);
353	
354	    await page.getByRole("button", { name: /Register User/ }).click();
355	
356	    await expect(
